```python
class Node:
    __slots__ = ("k", "v", "prev", "next")
    def __init__(self, k=None, v=None):
        self.k, self.v, self.prev, self.next = k, v, None, None

class LRUCache:
    def __init__(self, capacity: int):
        self.cap, self.map = capacity, {}
        self.head, self.tail = Node(), Node()
        self.head.next, self.tail.prev = self.tail, self.head

    def _pull(self, n):
        n.prev.next, n.next.prev = n.next, n.prev

    def _front(self, n):
        n.next, n.prev = self.head.next, self.head
        self.head.next.prev, self.head.next = n, n

    def get(self, k):
        n = self.map.get(k)
        if not n:
            return -1
        self._pull(n); self._front(n)
        return n.v

    def put(self, k, v):
        if k in self.map:
            n = self.map[k]; n.v = v
            self._pull(n); self._front(n); return
        n = Node(k, v); self.map[k] = n; self._front(n)
        if len(self.map) > self.cap:
            old = self.tail.prev
            self._pull(old); del self.map[old.k]
```

```js
export function debounce(fn, wait) {
  let t;
  return function (...args) {
    clearTimeout(t);
    t = setTimeout(() => fn.apply(this, args), wait);
  };
}
```

Each call resets the timer; only the last burst runs.
